<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Personal Expense Tracker</title>
  <style>
    * { box-sizing: border-box; }
    body { font-family: system-ui, sans-serif; max-width: 700px; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; }
    h1 { margin-bottom: 1.5rem; }
    .form-row { display: flex; gap: 0.5rem; flex-wrap: wrap; align-items: flex-end; margin-bottom: 1rem; }
    .form-row > div { flex: 1; min-width: 120px; }
    label { display: block; font-size: 0.85rem; margin-bottom: 0.25rem; font-weight: 500; }
    input, select { width: 100%; padding: 0.5rem; border: 1px solid #ccc; border-radius: 4px; font-size: 1rem; }
    input[type="number"] { width: 100%; }
    button { padding: 0.5rem 1rem; background: #2563eb; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 1rem; }
    button:hover { background: #1d4ed8; }
    .btn-del { background: #dc2626; padding: 0.25rem 0.5rem; font-size: 0.8rem; }
    .btn-del:hover { background: #b91c1c; }
    #form-error { color: #dc2626; min-height: 1.25rem; margin-bottom: 1rem; }
    .filters { display: flex; gap: 1rem; flex-wrap: wrap; margin-bottom: 1.5rem; padding: 1rem; background: #f8fafc; border-radius: 6px; }
    .filters > div { flex: 1; min-width: 150px; }
    table { width: 100%; border-collapse: collapse; margin-bottom: 1.5rem; }
    th, td { padding: 0.75rem; text-align: left; border-bottom: 1px solid #e5e7eb; }
    th { background: #f3f4f6; font-weight: 600; }
    .expense:hover { background: #f9fafb; }
    .amount { font-family: monospace; text-align: right; }
    .summary { display: flex; flex-wrap: wrap; gap: 1rem; padding: 1rem; background: #f0fdf4; border-radius: 6px; border: 1px solid #bbf7d0; }
    .summary > div { flex: 1; min-width: 120px; }
    .summary-label { font-size: 0.8rem; color: #6b7280; text-transform: uppercase; }
    .summary-value { font-size: 1.25rem; font-weight: 600; font-family: monospace; }
    .cat-summary { display: flex; flex-wrap: wrap; gap: 0.75rem; margin-top: 1rem; padding-top: 1rem; border-top: 1px solid #dcfce7; width: 100%; }
    .cat-item { background: white; padding: 0.5rem 1rem; border-radius: 4px; border: 1px solid #d1fae5; font-size: 0.9rem; }
    .cat-name { font-weight: 600; }
    .empty-state { text-align: center; color: #9ca3af; padding: 3rem; }
  </style>
</head>
<body>
  <h1>Personal Expense Tracker</h1>

  <form id="expense-form">
    <div class="form-row">
      <div>
        <label for="amount">Amount</label>
        <input type="number" id="amount" step="0.01" min="0.01" placeholder="0.00" required>
      </div>
      <div>
        <label for="category">Category</label>
        <select id="category" required>
          <option value="groceries">Groceries</option>
          <option value="transport">Transport</option>
          <option value="bills">Bills</option>
          <option value="fun">Fun</option>
        </select>
      </div>
    </div>
    <div class="form-row">
      <div>
        <label for="date">Date</label>
        <input type="date" id="date" required>
      </div>
      <div>
        <label for="note">Note (optional)</label>
        <input type="text" id="note" placeholder="Description...">
      </div>
    </div>
    <div class="form-row">
      <div style="flex: 0 0 auto;">
        <button type="submit" id="add-expense">Add Expense</button>
      </div>
    </div>
    <div id="form-error" aria-live="polite"></div>
  </form>

  <div class="filters">
    <div>
      <label for="filter-category">Category</label>
      <select id="filter-category">
        <option value="all">All</option>
        <option value="groceries">Groceries</option>
        <option value="transport">Transport</option>
        <option value="bills">Bills</option>
        <option value="fun">Fun</option>
      </select>
    </div>
    <div>
      <label for="filter-from">From</label>
      <input type="date" id="filter-from">
    </div>
    <div>
      <label for="filter-to">To</label>
      <input type="date" id="filter-to">
    </div>
  </div>

  <table id="expense-table">
    <thead>
      <tr>
        <th>Amount</th>
        <th>Category</th>
        <th>Date</th>
        <th>Note</th>
        <th></th>
      </tr>
    </thead>
    <tbody id="expense-list"></tbody>
  </table>

  <div class="summary">
    <div>
      <div class="summary-label">Total (filtered)</div>
      <div class="summary-value" id="total">0.00</div>
    </div>
    <div id="cat-summary" class="cat-summary"></div>
  </div>

  <script>
    const STORAGE_KEY = 'expenses_v1';
    const CATEGORIES = ['groceries', 'transport', 'bills', 'fun'];

    let expenses = [];

    const form = document.getElementById('expense-form');
    const amountInput = document.getElementById('amount');
    const categoryInput = document.getElementById('category');
    const dateInput = document.getElementById('date');
    const noteInput = document.getElementById('note');
    const errorEl = document.getElementById('form-error');
    const listEl = document.getElementById('expense-list');
    const totalEl = document.getElementById('total');
    const catSummaryEl = document.getElementById('cat-summary');
    const filterCat = document.getElementById('filter-category');
    const filterFrom = document.getElementById('filter-from');
    const filterTo = document.getElementById('filter-to');

    function load() {
      try {
        const data = localStorage.getItem(STORAGE_KEY);
        if (data) expenses = JSON.parse(data);
      } catch (e) {
        expenses = [];
      }
      render();
    }

    function save() {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses));
    }

    function formatMoney(n) {
      return n.toFixed(2);
    }

    function validateForm() {
      const amount = parseFloat(amountInput.value);
      const date = dateInput.value;
      if (!amountInput.value || isNaN(amount) || amount <= 0) {
        errorEl.textContent = 'Please enter a valid positive amount.';
        return false;
      }
      if (!date) {
        errorEl.textContent = 'Please select a date.';
        return false;
      }
      errorEl.textContent = '';
      return true;
    }

    function addExpense(e) {
      e.preventDefault();
      if (!validateForm()) return;

      const expense = {
        id: Date.now() + Math.random(),
        amount: parseFloat(amountInput.value),
        category: categoryInput.value,
        date: dateInput.value,
        note: noteInput.value.trim()
      };

      expenses.unshift(expense);
      save();
      render();

      amountInput.value = '';
      noteInput.value = '';
      amountInput.focus();
    }

    function deleteExpense(id) {
      expenses = expenses.filter(ex => ex.id !== id);
      save();
      render();
    }

    function matchesFilters(expense) {
      if (filterCat.value !== 'all' && expense.category !== filterCat.value) return false;
      if (filterFrom.value && expense.date < filterFrom.value) return false;
      if (filterTo.value && expense.date > filterTo.value) return false;
      return true;
    }

    function getVisibleExpenses() {
      return expenses.filter(matchesFilters);
    }

    function render() {
      const visible = getVisibleExpenses();

      // Render list
      listEl.innerHTML = '';
      if (visible.length === 0) {
        listEl.innerHTML = '<tr><td colspan="5" class="empty-state">No expenses found</td></tr>';
      } else {
        visible.forEach(expense => {
          const tr = document.createElement('tr');
          tr.className = 'expense';
          tr.innerHTML = `
            <td class="amount">${formatMoney(expense.amount)}</td>
            <td>${expense.category}</td>
            <td>${expense.date}</td>
            <td>${expense.note || ''}</td>
            <td><button class="btn-del exp-del" data-id="${expense.id}" aria-label="Delete">Delete</button></td>
          `;
          listEl.appendChild(tr);
        });
      }

      // Render total
      const total = visible.reduce((sum, ex) => sum + ex.amount, 0);
      totalEl.textContent = formatMoney(total);

      // Render category summary
      catSummaryEl.innerHTML = '';
      CATEGORIES.forEach(cat => {
        const catTotal = visible
          .filter(ex => ex.category === cat)
          .reduce((sum, ex) => sum + ex.amount, 0);
        const div = document.createElement('div');
        div.className = 'cat-item';
        div.setAttribute('data-cat', cat);
        div.innerHTML = `<span class="cat-name">${cat}:</span> ${formatMoney(catTotal)}`;
        catSummaryEl.appendChild(div);
      });
    }

    // Event listeners
    form.addEventListener('submit', addExpense);

    listEl.addEventListener('click', e => {
      if (e.target.matches('.exp-del')) {
        const id = Number(e.target.dataset.id);
        deleteExpense(id);
      }
    });

    [filterCat, filterFrom, filterTo].forEach(el => {
      el.addEventListener('change', render);
      el.addEventListener('input', render);
    });

    // Set default date to today
    const today = new Date().toISOString().split('T')[0];
    dateInput.value = today;

    load();
  </script>
</body>
</html>
